_sha512_block_asm::
        ; W[0..15] from the message. Each word is byte-reversed.
        ld hl, #_sha_data_p
        ld a, (hl+)
        ld h, (hl)
        ld l, a
        ld a, l
        ld (#_sha_ptr), a
        ld a, h
        ld (#_sha_ptr+1), a
        ld c, #0
sha_ldw:
        ld a, c
        call wptr
        ld a, l
        add a, #7
        ld l, a
        ld a, h
        adc a, #0
        ld h, a
        ld a, (#_sha_ptr)
        ld e, a
        ld a, (#_sha_ptr+1)
        ld d, a
        ld b, #8
sha_ldwb:
        ld a, (de)
        inc de
        ld (hl), a
        dec hl
        dec b
        jr nz, sha_ldwb
        ld a, e
        ld (#_sha_ptr), a
        ld a, d
        ld (#_sha_ptr+1), a
        inc c
        ld a, c
        cp a, #16
        jp nz, sha_ldw

        ld hl, #_sha_ctx_p
        ld a, (hl+)
        ld h, (hl)
        ld l, a
        ld de, #_sha_s
        ld b, #64
sha_cst:
        ld a, (hl+)
        ld (de), a
        inc de
        dec b
        jr nz, sha_cst

        ; Rounds 0..15 use the message words still sitting in W.
        xor a
        ld (#_sha_i), a
sha_rloop0:
        call sha_round
        ld hl, #_sha_i
        inc (hl)
        ld a, (hl)
        cp a, #16
        jp c, sha_rloop0

        ; W[i] = sigma1(W[i-2]) + W[i-7] + sigma0(W[i-15]) + W[i-16].
        ; Expand just before round i. Read W[i-16] before the store:
        ; that slot is the one this word replaces, and earlier rounds
        ; have already consumed it.
sha_sched:
        ld a, (#_sha_i)
        sub a, #2
        call set_src_w
        call sha_sigma1
        ld a, (#_sha_i)
        sub a, #15
        call set_src_w
        call sha_sigma0
        ld hl, #_sha_t1
        ld de, #_sha_s0
        call sha_addm
        ld a, (#_sha_i)
        sub a, #7
        call wptr
        ld d, h
        ld e, l
        ld hl, #_sha_t1
        call sha_addm
        ld a, (#_sha_i)
        sub a, #16
        call wptr
        ld d, h
        ld e, l
        ld hl, #_sha_t1
        call sha_addm
        ld a, (#_sha_i)
        call wptr
        ld d, h
        ld e, l
        ld hl, #_sha_t1
        call sha_copy8
        call sha_round
        ld hl, #_sha_i
        inc (hl)
        ld a, (hl)
        cp a, #80
        jp c, sha_sched

        ; 80 mod 8 is 0, so slot r is logical register r again.
        ld hl, #_sha_ctx_p
        ld a, (hl+)
        ld h, (hl)
        ld l, a
        ld de, #_sha_s
        call sha_addm
        call sha_addm
        call sha_addm
        call sha_addm
        call sha_addm
        call sha_addm
        call sha_addm
        call sha_addm
        ret

        .area _BSS
